package com.example.lending.application.service;

import com.example.lending.application.port.in.RegisterMemberUseCase;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.application.port.out.SaveMemberPort;
import com.example.lending.domain.Member;
import com.example.lending.domain.MemberAlreadyRegisteredException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.UUID;

@Service
@Transactional
public class RegisterMemberService implements RegisterMemberUseCase {

    private final LoadMemberPort loadMemberPort;
    private final SaveMemberPort saveMemberPort;

    public RegisterMemberService(LoadMemberPort loadMemberPort, SaveMemberPort saveMemberPort) {
        this.loadMemberPort = loadMemberPort;
        this.saveMemberPort = saveMemberPort;
    }

    @Override
    public Member registerMember(RegisterMemberCommand command) {
        if (command.memberId() == null) {
            Member member = Member.register(command.name());
            saveMemberPort.saveMember(member);
            return member;
        }
        // 저장은 덮어쓰기(merge)이므로 기존 회원 ID 로는 등록하지 않는다
        UUID memberId = command.memberId();
        if (loadMemberPort.loadMember(memberId).isPresent()) {
            throw new MemberAlreadyRegisteredException(memberId);
        }
        Member member = Member.register(memberId, command.name());
        saveMemberPort.saveMember(member);
        return member;
    }
}
